<?php include "auth.php";include "conection.php";$id=(int)($_GET['id']??0);$q=$conn->prepare("SELECT * FROM users WHERE id_user=?");$q->bind_param("i",$id);$q->execute();$d=$q->get_result()->fetch_assoc();if(!$d)die("Pengguna tidak ditemukan.");if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['nama_lengkap']);$u=trim($_POST['username']);$role=trim($_POST['role']);$p=$_POST['password']??'';if($p!==''){$h=password_hash($p,PASSWORD_DEFAULT);$s=$conn->prepare("UPDATE users SET nama_lengkap=?,username=?,password=?,role=? WHERE id_user=?");$s->bind_param("ssssi",$n,$u,$h,$role,$id);}else{$s=$conn->prepare("UPDATE users SET nama_lengkap=?,username=?,role=? WHERE id_user=?");$s->bind_param("sssi",$n,$u,$role,$id);}if($s->execute()){header("Location:admin.php");exit;}$error=$s->error;}$error=$error??'';?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Pengguna</title><link rel="stylesheet" href="./data.css?v=spiderman2026"></head><body><div class="app"><?php include "header.php";?><div class="form-card"><p class="eyebrow">PENGATURAN</p><h1>Edit Pengguna</h1><?php if($error):?><div class="alert error"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><div class="form-group"><label>Nama Lengkap</label><input name="nama_lengkap" value="<?=htmlspecialchars($d['nama_lengkap'])?>" required></div><div class="form-group"><label>Username</label><input name="username" value="<?=htmlspecialchars($d['username'])?>" required></div><div class="form-group"><label>Password Baru <span style="color:#98a2b3">(kosongkan jika tidak diubah)</span></label><input type="password" name="password"></div><div class="form-group"><label>Role</label><select name="role"><option <?=$d['role']==='Admin'?'selected':''?>>Admin</option><option <?=$d['role']==='Petugas'?'selected':''?>>Petugas</option></select></div><div class="actions"><a class="btn btn-secondary" href="admin.php">Kembali</a><button class="btn btn-primary">Simpan Perubahan</button></div></form></div><?php include "footer.php";?></div></body></html>